 "content": "def transform(grid):
    """Move each 4 down one row; when it is two rows above a full 2 bar,
    expand the point into an upward diagonal V, leaving the bar unchanged.
    """
    h, w = len(grid), len(grid[0])
    out = [[0] * w for _ in range(h)]
    bars = [r for r, row in enumerate(grid) if row and all(x == 2 for x in row)]
    bar = bars[0] if bars else None
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value == 2:
                out[r][c] = 2
            elif value == 4:
                nr = min(h - 1, r + 1)
                out[nr][c] = 4
                if bar is not None and r == bar - 2:
                    for k in range(1, nr + 1):
                        rr = nr - k
                        for cc in (c - k, c + k):
                            if 0 <= cc < w:
                                out[rr][cc] = 4
    return out
